package com.medtrack.inventory.service;
import com.fasterxml.jackson.core.JsonProcessingException; import com.fasterxml.jackson.databind.ObjectMapper; import com.medtrack.batch.entity.*; import com.medtrack.batch.repository.BatchRepository; import com.medtrack.inventory.dto.*; import com.medtrack.inventory.entity.*; import com.medtrack.inventory.repository.*; import com.medtrack.medicine.entity.*; import com.medtrack.medicine.repository.MedicineRepository; import com.medtrack.shared.exception.*; import com.medtrack.supplier.entity.Supplier; import com.medtrack.supplier.repository.SupplierRepository; import com.medtrack.user.entity.User; import com.medtrack.user.repository.UserRepository; import com.medtrack.warehouse.entity.*; import com.medtrack.warehouse.repository.*; import java.nio.charset.StandardCharsets; import java.security.*; import java.time.*; import java.util.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.*;
@Service public class InboundService {private static final String PATH="/api/v1/inventory/inbound";private final BatchRepository batches;private final MedicineRepository medicines;private final SupplierRepository suppliers;private final WarehouseRepository warehouses;private final StorageLocationRepository locations;private final InventoryBalanceRepository balances;private final IdempotencyKeyRepository keys;private final UserRepository users;private final DoubleEntryLedgerService ledger;private final CriticalAuditService audit;private final ObjectMapper json; public InboundService(BatchRepository b,MedicineRepository m,SupplierRepository s,WarehouseRepository w,StorageLocationRepository l,InventoryBalanceRepository ib,IdempotencyKeyRepository k,UserRepository u,DoubleEntryLedgerService d,CriticalAuditService a,ObjectMapper o){batches=b;medicines=m;suppliers=s;warehouses=w;locations=l;balances=ib;keys=k;users=u;ledger=d;audit=a;json=o;}
 @Transactional(isolation=Isolation.READ_COMMITTED) public InboundReceiptResponse receive(UUID actorId,String key,InboundReceiptRequest request){if(key==null||key.isBlank())throw new DomainException("IDEMPOTENCY_KEY_REQUIRED","X-Idempotency-Key is required");String fingerprint=fingerprint(request);keys.lock(actorId+":"+PATH+":"+key);Optional<IdempotencyKey> existing=keys.findByKeyAndUserIdAndRequestPath(key,actorId,PATH);if(existing.isPresent()){IdempotencyKey prior=existing.get();if(!prior.getRequestFingerprint().equals(fingerprint))throw new ConflictException("IDEMPOTENCY_KEY_REUSED","Idempotency key was already used for a different request");if(prior.getResponseBody()!=null)return read(prior.getResponseBody());throw new ConflictException("IDEMPOTENCY_REQUEST_IN_PROGRESS","Idempotency request is still processing");}IdempotencyKey record=keys.save(new IdempotencyKey(key,actorId,PATH,fingerprint,Instant.now().plus(Duration.ofHours(24))));User actor=users.findById(actorId).orElseThrow(()->new NotFoundException("User"));Warehouse warehouse=warehouses.findById(request.warehouseId()).orElseThrow(()->new NotFoundException("Warehouse"));authorize(actor,warehouse);StorageLocation location=locations.findById(request.storageLocationId()).orElseThrow(()->new NotFoundException("Storage location"));if(!location.getWarehouse().getId().equals(warehouse.getId()))throw new DomainException("STORAGE_LOCATION_MISMATCH","Storage location does not belong to the selected warehouse");Medicine medicine=medicines.findById(request.medicineId()).orElseThrow(()->new NotFoundException("Medicine"));if(medicine.getStatus()!=MedicineStatus.ACTIVE)throw new DomainException("MEDICINE_DISCONTINUED","Discontinued medicine cannot receive stock");validateDates(request,medicine);if(batches.existsByMedicine_IdAndBatchNumber(medicine.getId(),request.batchNumber()))throw new ConflictException("DUPLICATE_BATCH_NUMBER","Batch number already exists for this medicine");Supplier supplier=suppliers.findById(request.supplierId()).orElseThrow(()->new NotFoundException("Supplier"));Batch batch=batches.save(new Batch(request.batchNumber(),medicine,supplier,request.manufacturingDate(),request.expiryDate(),request.quantity(),BatchStatus.ACTIVE));InventoryBalance balance=new InventoryBalance(warehouse,batch,location);InventoryLedgerLine debit=InventoryLedgerLine.physical(batch,warehouse,LedgerDirection.DEBIT,request.quantity(),balance,request.quantity(),0,0);balance.receive(request.quantity());balances.save(balance);InventoryJournalEntry journal=ledger.record(JournalEntryType.INBOUND_RECEIPT,"BATCH",batch.getId(),actor,"Inbound receipt for batch "+batch.getBatchNumber(),List.of(debit,InventoryLedgerLine.offset(batch,AccountType.SUPPLIER_OFFSET,LedgerDirection.CREDIT,request.quantity())));InboundReceiptResponse response=new InboundReceiptResponse(batch.getId(),balance.getId(),journal.getEntryNumber(),balance.getAvailableQuantity());audit.record(actorId,"INBOUND_RECEIPT","BATCH",batch.getId(),write(response));record.complete(201,write(response));return response;}
 private void authorize(User actor,Warehouse w){if(w.getStatus()!=WarehouseStatus.ACTIVE||w.getType()!=WarehouseType.CENTRAL_WAREHOUSE)throw new DomainException("INVALID_INBOUND_WAREHOUSE","Inbound receiving requires an active central warehouse");String role=actor.getRole().getName();if("SUPER_ADMIN".equals(role))return;if("CENTRAL_WAREHOUSE_MANAGER".equals(role)&&actor.getAssignedWarehouse()!=null&&actor.getAssignedWarehouse().getId().equals(w.getId()))return;throw new ConflictException("INBOUND_WAREHOUSE_NOT_ALLOWED","User is not allowed to receive stock into this warehouse");} private void validateDates(InboundReceiptRequest r,Medicine m){if(!r.expiryDate().isAfter(r.manufacturingDate()))throw new DomainException("BATCH_EXPIRY_INVALID","Batch expiry date must be after manufacturing date");if(r.expiryDate().isBefore(LocalDate.now().plusDays(m.getMinReceivingShelfLifeDays())))throw new DomainException("BATCH_EXPIRY_TOO_SOON","Batch expiry date fails minimum receiving shelf-life requirement ("+m.getMinReceivingShelfLifeDays()+" days required)");} private String fingerprint(InboundReceiptRequest request){return digest(write(request));} private String digest(String value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}} private String write(Object value){try{return json.writeValueAsString(value);}catch(JsonProcessingException e){throw new IllegalStateException(e);}} private InboundReceiptResponse read(String body){try{return json.readValue(body,InboundReceiptResponse.class);}catch(JsonProcessingException e){throw new IllegalStateException(e);}}}
